const daftar = document.querySelector("#daftar");
const ringkasan = document.querySelector("#ringkasan");
daftar.innerHTML = "<li>Kopi</li><li>Teh</li><li>Jus</li>";
ringkasan.textContent = "3 menu";
console.log(document.querySelectorAll("#daftar li").length);
console.log(document.querySelector("#daftar li").textContent);
console.log(ringkasan.textContent);
